<p><span style="text-decoration: underline;"><strong>Round Robin</strong></span></p>
<p>#include&lt;stdio.h&gt;<br />main()<br />{<br />int i,j,n,bu[10],wa[10],tat[10],t,ct[10],max;<br />float awt=0,att=0,temp=0;<br />clrscr();<br />printf("Enter the no of processes -- ");<br />scanf("%d",&amp;n);<br />for(i=0;i&lt;n;i++)<br />{<br />printf("\nEnter Burst Time for process %d -- ", i+1);<br />scanf("%d",&amp;bu[i]);<br />ct[i]=bu[i];<br />}<br />printf("\nEnter the size of time slice -- ");<br />scanf("%d",&amp;t);<br />max=bu[0];<br />for(i=1;i&lt;n;i++)<br />if(max&lt;bu[i])<br />max=bu[i];<br />for(j=0;j&lt;(max/t)+1;j++)<br />for(i=0;i&lt;n;i++)<br />if(bu[i]!=0)<br /> if(bu[i]&lt;=t)<br /> {<br />tat[i]=temp+bu[i];<br />temp=temp+bu[i];<br />bu[i]=0;<br /> }<br /> else<br /> {<br />bu[i]=bu[i]-t;<br />temp=temp+t;<br /> }<br />for(i=0;i&lt;n;i++)<br /> {<br />wa[i]=tat[i]-ct[i];<br />att+=tat[i];<br />awt+=wa[i];<br /> }<br />printf("\nThe Average Turnaround time is -- %f",att/n);<br />printf("\nThe Average Waiting time is -- %f ",awt/n);<br />printf("\n\tPROCESS\t BURST TIME \t WAITING TIME\tTURNAROUND TIME\n");<br />for(i=0;i&lt;n;i++)<br />printf("\t%d \t %d \t\t %d \t\t %d \n",i+1,ct[i],wa[i],tat[i]);<br />getch();<br />}</p>